class Repo { var cachedUser: User? = null }

suspend fun example(repo: Repo) {
    val user = repo.cachedUser ?: return // capture as an immutable local first
    delay(100) // suspension point — repo.cachedUser could theoretically change elsewhere
    println(user.name) // still safe — 'user' is a local val, unaffected by later mutation
}

sealed interface Status { data object Active : Status; data object Inactive : Status }

fun describe(status: Status?): String = when (status) {
    Status.Active -> "active"
    Status.Inactive -> "inactive"
    null -> "unknown" // required — status is nullable, not just Status
}
